function commissionBlocker(s,route){const p=commissionPlan(s,route);if(!p)return 'Choose a coastal settlement.';if(s.fleet.development[route]!==3)return 'Complete all three settlement projects to open commissions.';return canAfford(s,p.cost,p.goal)?'':'Prepare the commission supplies or release other reservations.';}
