function fundFerryStage(s,expectedStage){if(expectedStage!==s.ferry.stage||ferryFundingBlocker(s))return false;const goal='ferryfund:'+s.ferry.stage;spend(s,FERRY_STAGES[s.ferry.stage].cost,goal);releaseReservation(s,goal);s.ferry.funded=true;note(s,FERRY_STAGES[s.ferry.stage].name+' funded · three supply batches needed');return true;}
function ferryDeliveryBlocker(s){if(!ferryEligible(s))return 'Open the neighbourhood and complete the lighthouse first.';if(s.ferry.stage===3)return 'The passenger terminal is complete.';if(!s.ferry.funded)return 'Fund this terminal stage first.';const goal=`ferry:${s.ferry.stage}:${s.ferry.delivered}`;return canAfford(s,FERRY_STAGES[s.ferry.stage].supplies,goal)?'':'Prepare the supply batch shown below or release other reservations.';}
function deliverFerrySupplies(s,expectedStage,expectedDelivered){if(expectedStage!==s.ferry.stage||expectedDelivered!==s.ferry.delivered||ferryDeliveryBlocker(s))return false;const stage=s.ferry.stage,d=FERRY_STAGES[stage],goal=`ferry:${stage}:${s.ferry.delivered}`;spend(s,d.supplies,goal);releaseReservation(s,goal);s.ferry.delivered++;if(s.ferry.delivered===3){s.ferry.stage++;s.ferry.funded=false;s.ferry.delivered=0;note(s,d.name+' complete'+(s.ferry.stage===3?' · passenger services now available':''));}else note(s,d.name+' · '+s.ferry.delivered+' of 3 supply batches delivered');return true;}
function ferryPlan(s,slot,destination){const b=fleetBoat(s,slot),d=Object.hasOwn(FERRY_SERVICES,destination)?FERRY_SERVICES[destination]:null;if(!b||!d)return null;const boat=FLEET_BOATS[b.type],up=b.upgrade?FLEET_UPGRADES[b.upgrade]:null,scale=boat.cargoScale*(up?.cargoScale||1),scaled=packet=>Object.fromEntries(Object.entries(packet).map(([k,n])=>[k,Math.ceil(n*scale)]));return {route:destination,tier:1,name:d.name,destination:FLEET_ROUTES[destination].name,cost:scaled(d.cost),reward:scaled(d.reward),duration:Math.ceil(d.duration*boat.timeScale*(up?.timeScale||1)*(s.fleet.development.island>=2?.85:1)*(b.sails?.9:1)),goal:`ferryservice:${slot}:${destination}`};}
