function ferryGuide(s){if(s.ferry.stage<3){const d=FERRY_STAGES[s.ferry.stage];return {step:s.ferry.stage,title:d.name,description:s.ferry.funded?`Deliver supply batch ${s.ferry.delivered+1} of 3. Delivered goods are saved permanently for this stage.`:'Fund the stage, then deliver three batches from your existing workshops.',label:s.ferry.funded?'Deliver terminal supplies':'Plan the passenger terminal',target:'ferry'};}if(!s.ferry.runs)return {step:3,title:'Your first passenger service',description:'Choose an idle boat and provision a passenger run. Fares offer an alternative to cargo trade.',label:'Plan a ferry service',target:'ferry'};return {step:4,title:'A working passenger terminal',description:'Balance food supplies and boat time between passengers, cargo and coastal projects.',label:'Manage passenger services',target:'ferry'};}
