 return missing.length?'Prepare city cargo: '+missing.map(([k,n])=>(E.ITEMS[k]?.name||k)+' '+Math.min(n,E.available(s,k)+(c.reservations['city:'+slot]?.[k]||0))+'/'+n).join(' · ')+'. Use Plan supplies to make the remainder.':'';
